1	import 'dart:async';
2	import 'dart:io';
3	
4	import 'package:flutter_bloc/flutter_bloc.dart';
5	
6	import '../../../entries/domain/entities/entry.dart';
7	import '../../../entries/domain/repositories/entries_repository.dart';
8	import '../../domain/services/audio_transcriber.dart';
9	import '../../domain/services/mic_recorder.dart';
10	
11	/// `AudioEntryCubit`'s own sealed state hierarchy — separate from
12	/// `TextEntryState` (Boundaries: "own sealed `AudioCaptureState`,
13	/// separate from `TextEntryState`"). Unlike `TextEntryState`, no common
14	/// base-class field: the 5 variants don't share a uniform shape the way
15	/// every `TextEntryState` always carries `activeTab`/`text` — [AudioIdle]
16	/// genuinely has nothing in common with [AudioTranscribed], for instance.
17	sealed class AudioCaptureState {
18	  const AudioCaptureState();
19	}
20	
21	/// The state immediately after the modal opens on the Áudio tab exits
22	/// (Never: this story's trivial cross-tab case), and the state a fresh
23	/// `AudioEntryCubit` always starts in.
24	class AudioIdle extends AudioCaptureState {
25	  const AudioIdle();
26	}
27	
28	/// Recording in progress — [elapsedSeconds] backs the running monospace
29	/// timer (Acceptance Criteria) and ticks once per second via
30	/// `AudioEntryCubit`'s own internal `Timer.periodic`.
31	class AudioRecording extends AudioCaptureState {
32	  const AudioRecording({required this.elapsedSeconds});
33	
34	  final int elapsedSeconds;
35	}
36	
37	/// Recording stopped, `AudioTranscriber.transcribe()` in flight —
38	/// `InsertionModal`'s own `_AudioTab` freezes the waveform at 35% opacity
39	/// for the whole duration of this state (Acceptance Criteria).
40	class AudioProcessing extends AudioCaptureState {
41	  const AudioProcessing({required this.path, required this.durationSeconds});
42	
43	  final String path;
44	  final int durationSeconds;
45	}
46	
47	/// Transcription succeeded (even to an empty string) — [text] is editable
48	/// before Salvar (Acceptance Criteria), mirrored into this state by
49	/// `AudioEntryCubit.updateText` the same way `TextEntryCubit.updateText`
50	/// mirrors the Texto field. [saving] is this story's `TextEntrySaving`
51	/// equivalent folded into one state instead of a separate sibling class —
52	/// both [path]/[durationSeconds] (needed for the eventual `create()` call)
53	/// stay fixed across a save attempt, so there's nothing a sibling state
54	/// would add that a boolean field doesn't already cover just as clearly.
55	class AudioTranscribed extends AudioCaptureState {
56	  const AudioTranscribed({
57	    required this.path,
58	    required this.durationSeconds,
59	    required this.text,
60	    required this.saving,
61	  });
62	
63	  final String path;
64	  final int durationSeconds;
65	  final String text;
66	  final bool saving;
67	
68	  AudioTranscribed copyWith({String? text, bool? saving}) => AudioTranscribed(
69	    path: path,
70	    durationSeconds: durationSeconds,
71	    text: text ?? this.text,
72	    saving: saving ?? this.saving,
73	  );
74	}
75	
76	/// A save attempt from [AudioTranscribed] succeeded — `InsertionModal`'s
77	/// listener reacts to this exactly like `TextEntrySaved` (announce, then
78	/// pop). Terminal, same rationale as `TextEntrySaved`'s own doc.
79	class AudioSaved extends AudioCaptureState {
80	  const AudioSaved();
81	}
82	
83	/// The last attempt failed — covers all 3 failure rows of the I/O matrix:
84	/// - Mic permission denied -> [path]/[durationSeconds] both `null` ("No
85	///   file to preserve"); [AudioEntryCubit.retry] re-requests permission.
86	/// - Transcription failed -> [path]/[durationSeconds] carry the preserved
87	///   file; [AudioEntryCubit.retry] re-transcribes it, never re-records.
88	/// - Save failed (incl. offline) -> same preserved [path]/
89	///   [durationSeconds]/[text] semantics as `TextEntryError`; the modal's
90	///   `_AudioTab` keeps showing the editable text with Salvar re-enabled
91	///   rather than routing back through [AudioEntryCubit.retry].
92	class AudioError extends AudioCaptureState {
93	  const AudioError({
94	    required this.path,
95	    required this.durationSeconds,
96	    required this.message,
97	    this.text,
98	  });
99	
100	  final String? path;
101	  final int? durationSeconds;
102	  final String message;
103	
104	  /// Non-null only for a save failure — lets `_AudioTab` keep rendering
105	  /// the editable text field under the inline error, same as
106	  /// `TextEntryError`'s own `_TextoTab` rendering.
107	  final String? text;
108	}
109	
110	/// Drives the Áudio tab's recording -> processing -> transcribed/error
111	/// pipeline (Intent). A fresh, `get_it`-factory-scoped instance per "+"
112	/// tap, same convention as `TextEntryCubit` — [MicRecorder]/
113	/// [AudioTranscriber] themselves stay long-lived `get_it` singletons
114	/// (`capture_injection.dart`), shared across every modal open the way
115	/// `EntriesRepository` already is for `TextEntryCubit`.
116	class AudioEntryCubit extends Cubit<AudioCaptureState> {
117	  AudioEntryCubit(this._micRecorder, this._audioTranscriber, this._repository)
118	    : super(const AudioIdle());
119	
120	  final MicRecorder _micRecorder;
121	  final AudioTranscriber _audioTranscriber;
122	  final EntriesRepository _repository;
123	
124	  Timer? _elapsedTimer;
125	
126	  /// Bumped by [cancel] so an in-flight [startRecording]/[stopRecording]
127	  /// continuation can tell "the user already left the Áudio tab while I
128	  /// was awaiting" apart from "nothing has changed since I started" —
129	  /// the same role `isClosed` already plays for `close()`, but for a tab
130	  /// switch that doesn't close the cubit itself (Review finding: without
131	  /// this, `cancel()` running mid-await either left the recorder running
132	  /// unobserved, or let a stale `stop()`/transcription result resurrect a
133	  /// flow the user already left).
134	  int _generation = 0;
135	
136	  /// Forwarded straight from [MicRecorder.amplitudeStream] — lets
137	  /// `_AudioTab`'s waveform animate without ever importing `package:record`
138	  /// itself (Boundaries).
139	  Stream<double> get amplitudeStream => _micRecorder.amplitudeStream;
140	
141	  /// Starts recording — called from `InsertionModal`'s tab-switch
142	  /// listener the instant the Áudio tab becomes active (Acceptance
143	  /// Criteria: "recording starts immediately"), and again by [retry] when
144	  /// the last attempt failed before any file ever existed (permission
145	  /// denied). Ignored while a recording is already in progress, and —
146	  /// Review finding — ignored once the pipeline has moved past recording
147	  /// ([AudioProcessing]/[AudioTranscribed]/an [AudioError] that still
148	  /// carries a file): without this, re-entering the Áudio tab after a
149	  /// completed transcription silently discarded the transcribed text and
150	  /// started a brand-new recording over it. Only [AudioIdle] (fresh) or
151	  /// an [AudioError] with no file (nothing to discard) actually start.
152	  Future<void> startRecording() async {
153	    final current = state;
154	    final canStart =
155	        current is AudioIdle ||
156	        (current is AudioError && current.path == null);
157	    if (!canStart) {
158	      return;
159	    }
160	    final generation = ++_generation;
161	    final hasPermission = await _micRecorder.hasPermission();
162	    if (isClosed || generation != _generation) {
163	      return;
164	    }
165	    if (!hasPermission) {
166	      emit(
167	        const AudioError(
168	          path: null,
169	          durationSeconds: null,
170	          message:
171	              'Permissão de microfone negada. Toque em "Tentar novamente" '
172	              'para permitir o acesso.',
173	        ),
174	      );
175	      return;
176	    }
177	    await _micRecorder.start();
178	    if (isClosed || generation != _generation) {
179	      // Review finding: `cancel()` bumped `_generation` (the user already
180	      // left the Áudio tab) while `start()` was in flight — stop/discard
181	      // the session we just started instead of leaving a live, unobserved
182	      // recording running.
183	      unawaited(_micRecorder.cancel());
184	      return;
185	    }
186	    _startElapsedTimer();
187	    emit(const AudioRecording(elapsedSeconds: 0));
188	  }
189	
190	  void _startElapsedTimer() {
191	    _elapsedTimer?.cancel();
192	    var elapsed = 0;
193	    _elapsedTimer = Timer.periodic(const Duration(seconds: 1), (_) {
194	      elapsed++;
195	      if (state is AudioRecording) {
196	        emit(AudioRecording(elapsedSeconds: elapsed));
197	      }
198	    });
199	  }
200	
201	  /// Stops recording and immediately kicks off transcription — the I/O
202	  /// matrix's "Happy path"/"Transcription fails" rows. Ignored outside
203	  /// [AudioRecording] (e.g. a stray second tap on the stop control).
204	  Future<void> stopRecording() async {
205	    if (state is! AudioRecording) {
206	      return;
207	    }
208	    final generation = _generation;
209	    _elapsedTimer?.cancel();
210	    final recording = await _micRecorder.stop();
211	    // Review finding: without the `_generation` check, a `cancel()` that
212	    // ran while `_micRecorder.stop()` was in flight (tab switch right
213	    // after tapping stop) already reset the cubit to `AudioIdle` — this
214	    // continuation must not resurrect the flow with a stale
215	    // `AudioProcessing`/`AudioError` emission on top of that reset.
216	    if (isClosed || generation != _generation) {
217	      return;
218	    }
219	    if (recording == null) {
220	      // Stopped with nothing actually captured — the I/O matrix has no
221	      // dedicated row for this (it should be unreachable in practice: the
222	      // recorder was just started above), but `AudioError` with no file
223	      // still gives the user a path back in via retry's permission-
224	      // re-request branch rather than leaving the cubit stuck mid-flow.
225	      emit(
226	        const AudioError(
227	          path: null,
228	          durationSeconds: null,
229	          message: 'Não foi possível gravar o áudio.',
230	        ),
231	      );
232	      return;
233	    }
234	    emit(
235	      AudioProcessing(
236	        path: recording.path,
237	        durationSeconds: recording.durationSeconds,
238	      ),
239	    );
240	    await _transcribe(recording.path, recording.durationSeconds);
241	  }
242	
243	  Future<void> _transcribe(String path, int durationSeconds) async {
244	    final text = await _audioTranscriber.transcribe(path);
245	    if (isClosed) {
246	      return;
247	    }
248	    // Guards a tab switch away mid-processing (`cancel()`, below) that
249	    // already reset the state to `AudioIdle` by the time this resolves —
250	    // without this, the eventual transcription result would still land
251	    // and resurrect a flow the user already left.
252	    if (state is! AudioProcessing ||
253	        (state as AudioProcessing).path != path) {
254	      return;
255	    }
256	    if (text == null) {
257	      emit(
258	        AudioError(
259	          path: path,
260	          durationSeconds: durationSeconds,
261	          message: 'Não foi possível transcrever o áudio.',
262	        ),
263	      );
264	      return;
265	    }
266	    emit(
267	      AudioTranscribed(
268	        path: path,
269	        durationSeconds: durationSeconds,
270	        text: text,
271	        saving: false,
272	      ),
273	    );
274	  }
275	
276	  /// "Tentar novamente" — re-requests permission when no file was ever
277	  /// recorded, or re-transcribes the same preserved file otherwise (I/O
278	  /// matrix: never re-records, never auto-retries on its own). A no-op
279	  /// outside [AudioError], or for a save failure (non-null [AudioError.
280	  /// text]) — that case's own retry is just tapping Salvar again, handled
281	  /// by [save] directly, not this method.
282	  Future<void> retry() async {
283	    final current = state;
284	    if (current is! AudioError || current.text != null) {
285	      return;
286	    }
287	    final path = current.path;
288	    final durationSeconds = current.durationSeconds;
289	    if (path == null || durationSeconds == null) {
290	      await startRecording();
291	      return;
292	    }
293	    emit(AudioProcessing(path: path, durationSeconds: durationSeconds));
294	    await _transcribe(path, durationSeconds);
295	  }
296	
297	  /// Mirrors the Texto field's own `updateText` — keeps the transcribed
298	  /// text editable before Salvar (Acceptance Criteria). Ignored while a
299	  /// save is already in flight, same rationale as `TextEntryCubit.
300	  /// updateText`.
301	  void updateText(String text) {
302	    final current = state;
303	    if (current is AudioTranscribed && !current.saving) {
304	      emit(current.copyWith(text: text));
305	    } else if (current is AudioError && current.text != null) {
306	      // Review finding: a save failure (`AudioError` with non-null
307	      // `text`) renders the same editable field as `AudioTranscribed`
308	      // (`_AudioErrorView`'s non-retry branch) — without this branch,
309	      // typing there updated the `TextField`'s own controller visually
310	      // but never the cubit's record of the text, so a retried `save()`
311	      // would silently resend the stale pre-failure text.
312	      emit(
313	        AudioError(
314	          path: current.path,
315	          durationSeconds: current.durationSeconds,
316	          message: current.message,
317	          text: text,
318	        ),
319	      );
320	    }
321	  }
322	
323	  /// Called when the Áudio tab loses focus mid-recording/mid-processing
324	  /// (`InsertionModal`'s tab-switch listener) — the I/O matrix's "Leave
325	  /// tab mid-recording" row: stops/releases the recorder, no `create()`
326	  /// ever fires. A no-op for every other state — in particular
327	  /// [AudioTranscribed]/[AudioError], where the Never clause's trivial
328	  /// scope (resource safety only, not full Story 3.4 cancel-safety) means
329	  /// leaving the tab must preserve the result rather than discard it.
330	  Future<void> cancel() async {
331	    // Bumped unconditionally — including when the state below doesn't
332	    // match either branch — so an in-flight `startRecording()`/
333	    // `stopRecording()` continuation still sees the mismatch and aborts
334	    // itself (Review finding: previously only invalidated a flow already
335	    // visible in `state`, missing the window while those methods were
336	    // still awaiting).
337	    _generation++;
338	    final current = state;
339	    if (current is AudioRecording) {
340	      _elapsedTimer?.cancel();
341	      await _micRecorder.cancel();
342	      if (isClosed) {
343	        return;
344	      }
345	      emit(const AudioIdle());
346	    } else if (current is AudioProcessing) {
347	      // The recorder itself is already stopped by the time this state is
348	      // reached (`stopRecording` stops it before emitting `AudioProcessing`)
349	      // — only resetting the cubit's own state is left, so the pending
350	      // `_transcribe` continuation's own `state is! AudioProcessing` guard
351	      // (above) drops its result instead of resurrecting this flow. Review
352	      // finding: the already-recorded file is abandoned for good at this
353	      // point (nothing will ever retry it), so it must be deleted here —
354	      // the other orphan-file case `_micRecorder.cancel()` above already
355	      // handles on its own.
356	      unawaited(_deleteRecordingFile(current.path));
357	      emit(const AudioIdle());
358	    }
359	  }
360	
361	  /// I/O matrix's "Happy path"/"Save fails" rows: fires `POST /entries`
362	  /// with `source: audio` and `mediaDurationSeconds` for the current
363	  /// transcribed text. Mirrors `TextEntryCubit.save()`'s `isClosed`/
364	  /// no-double-submit guards exactly (Boundaries).
365	  ///
366	  /// Review finding: also callable from an [AudioError] save failure
367	  /// (non-null [AudioError.text]) — `_AudioErrorView`'s non-retry branch
368	  /// re-renders the editable field and calls this same method for its
369	  /// "Salvar" button, but the original guard only matched
370	  /// [AudioTranscribed], making a retry after any save failure a
371	  /// permanent no-op.
372	  Future<void> save() async {
373	    final current = state;
374	    final String path;
375	    final int durationSeconds;
376	    final String text;
377	    if (current is AudioTranscribed && !current.saving) {
378	      path = current.path;
379	      durationSeconds = current.durationSeconds;
380	      text = current.text.trim();
381	    } else if (current is AudioError &&
382	        current.text != null &&
383	        current.path != null &&
384	        current.durationSeconds != null) {
385	      path = current.path!;
386	      durationSeconds = current.durationSeconds!;
387	      text = current.text!.trim();
388	    } else {
389	      return;
390	    }
391	    if (text.isEmpty) {
392	      return;
393	    }
394	    emit(
395	      AudioTranscribed(
396	        path: path,
397	        durationSeconds: durationSeconds,
398	        text: text,
399	        saving: true,
400	      ),
401	    );
402	    final result = await _repository.create(
403	      content: text,
404	      source: EntrySource.audio,
405	      mediaDurationSeconds: durationSeconds,
406	    );
407	    // Mirrors `TextEntryCubit.save()`'s own `isClosed` guard — this
408	    // cubit's `close()` can race the awaited call above (e.g. the modal's
409	    // barrier is dismissed mid-save).
410	    if (isClosed) {
411	      return;
412	    }
413	    result.match(
414	      (failure) => emit(
415	        AudioError(
416	          path: path,
417	          durationSeconds: durationSeconds,
418	          message: failure.message,
419	          text: text,
420	        ),
421	      ),
422	      (_) {
423	        // Review finding: the recorded temp file was never deleted after
424	        // a successful save — fire-and-forget, a deletion failure must
425	        // never block the modal from closing.
426	        unawaited(_deleteRecordingFile(path));
427	        emit(const AudioSaved());
428	      },
429	    );
430	  }
431	
432	  /// Best-effort cleanup for a temp recording file this cubit is done
433	  /// with (saved successfully, or abandoned for good by [cancel] mid-
434	  /// processing) — deletion failures are swallowed since nothing in the
435	  /// UI depends on this succeeding (Review finding: previously never
436	  /// called at all, leaking a `.wav` file per recording indefinitely).
437	  Future<void> _deleteRecordingFile(String path) async {
438	    try {
439	      await File(path).delete();
440	    } catch (_) {
441	      // Best-effort — a missing/already-deleted file, or a transient
442	      // disk error, is never worth surfacing to the user.
443	    }
444	  }
445	
446	  @override
447	  Future<void> close() {
448	    _elapsedTimer?.cancel();
449	    return super.close();
450	  }
