73	  /// finding: the Áudio tab had no equivalent coverage of its own
74	  /// `isSaving` gating the tab bar/close button).
75	  Completer<void>? gate;
76	
77	  @override
78	  Future<Either<Failure, Entry>> create({
79	    required String content,
80	    required EntrySource source,
81	    int? mediaDurationSeconds,
82	  }) async {
83	    createCallCount++;
84	    lastSource = source;
85	    lastMediaDurationSeconds = mediaDurationSeconds;
86	    final activeGate = gate;
87	    if (activeGate != null) {
88	      await activeGate.future;
89	    }
90	    return nextResult!();
91	  }
92	}
